#!/usr/bin/env python3
"""Reviewed instant spells: stages stay explicit; unsupported consequences stay partial."""
import copy,json,sys
from pathlib import Path
from edition_2024 import dice, META
source=Path(sys.argv[1]);root=Path(sys.argv[2]);root.mkdir(parents=True,exist_ok=True)
s={x['id']:x for x in json.loads((source/'after-5.json').read_text())};e={x['id']:x for x in json.loads((source/'after-15.json').read_text())}
plans={};effects=[]
def patch(id,fields,note,status='partial'):
 x=s[id];p=plans.setdefault(id,{'id':id,'name':x['name'],'changes':{},'effectsBefore':x['data'].get('status_effects',[]),'metadataBefore':{k:x.get(k) for k in META}})
 p['changes'].update({k:{'before':x['data'].get(k),'after':v} for k,v in fields.items()})
 p.update(automationStatus=status,automationNote=note,requiresPlayerInteraction=False)
def damage(base,add=(),save='',on='half',attack=False,scaling='slot'):
 r={'dices':dice(base),'addon':dice(add),'scaling':scaling if add else 'none'}
 if attack:r['range_attack']=True
 if save:r.update(save_ability=save,save_effect=on)
 return r
def stage(label,rule,condition=''):
 return {'kind':'damage','label':label,**rule,**({'save_condition':condition} if condition else {})}
def effect(id,old,condition,duration=None,rules=None,desc=None):
 data=copy.deepcopy(e[old]['data']);key=f'spell_{id}_impact_{old}'
 duration=duration or copy.deepcopy(data['duration'])
 data.update(code=key,concentration=False,duration=duration,application_sources=[{'item':{'id':id},'key':key,'target':'other','condition':condition}])
 if rules is not None:data['derived_effects']=rules
 if desc:data['desc']=desc
 effects.append({'spellId':id,'key':key,'name':s[id]['name']+': '+e[old]['name'].split(': ')[-1].lower(),'nameEn':'','data':data,'duration':duration,'condition':condition,'apply_on':'impact'})
# Direct damage and saves. Context restrictions remain visible in the save request.
for id,base,add,save,condition,status in [
 (6125,[(1,10,1)],[(1,10,1)],'dex','После попадания дальнобойным оружием; цель атаки и существа в 5 футах.','full'),
 (6131,[(3,6,11)],[(1,6,11)],'wis','При провале цель немедленно использует реакцию для безопасного отхода.','full'),
 (6137,[(3,8,6)],[(1,8,6)],'con','Конструкты бросают с помехой.','partial'),
 (6154,[(10,12,11)],[],'int','При провале также запрещены сотворение и действие Магия; повторный спасбросок раз в 30 дней.','partial'),
 (6199,[(10,6,13)],[(1,6,13)],'con','При взрыве шара.','partial'),
 (6239,[(5,6,5),(5,6,7)],[(1,6,5),(1,6,7)],'dex','','full'),
 (6287,[(7,8,10)],[],'con','Убитый гуманоид поднимается зомби в начале следующего хода заклинателя.','partial'),
 (6310,[(14,6,10)],[],'con','При провале максимум ХП уменьшается на фактически полученный некротический урон, не ниже 1.','partial'),
 (6328,[(8,8,12)],[],'dex','','full'),
 (6334,[(5,8,12)],[(1,8,12)],'dex','','full'),
 (6360,[(10,6,12)],[(3,6,12)],'dex','При снижении ХП до 0 цель и немагическое снаряжение распадаются.','partial'),
 (6368,[(2,6,10)],[(1,6,10)],'str','При провале также нельзя совершать реакции до начала следующего хода цели.','partial'),
 (6378,[(8,6,11)],[],'int','','partial'),
 (6397,[(12,6,7)],[],'con','','partial'),
 (6436,[(8,8,10)],[(1,8,10)],'con','Растения автоматически проваливают спасбросок.','partial'),
 (6446,[(10,8,9)],[],'dex','До 4 разных целей, +1 за круг выше 6-го; дополнительные цели в 30 футах от первой.','partial')]:
 r=damage(base,add,save,'negate' if id==6360 else 'half')
 if id in [6287,6360]:r['dices'][0]['bonus']=30 if id==6287 else 40
 if condition:r['save_condition']=condition
 note='Правила 2024: типизированная формула, усиление и спасбросок нужного этапа, применение урона в хронике. '
 remains={6137:'Помеху конструкта выбирает мастер.',6154:'Запрет магии и многодневное снятие пока вручную.',6199:'Отложенный переносимый шар, взрыв по таймеру и захват льдом ещё не автоматизированы.',6287:'Создание подконтрольного зомби пока вручную.',6310:'Связанное уменьшение максимума ХП пока вручную.',6360:'Распад тела, снаряжения и ограничение воскрешения пока вручную.',6368:'Запрет реакций пока вручную.',6378:'Эффект и повторный спасбросок поддержаны; штраф именно к концентрации пока вручную.',6397:'Помеха ослеплённого и повторный спасбросок поддержаны; атаки по ослеплённой цели и рассеивание тьмы пока вручную.',6436:'Автопровал растения выбирает мастер; воздействие на обычные растения разрешается по описанию.',6446:'Разветвлённый лимит целей и дальность от первой цели проверяет мастер.'}
 patch(id,{'damage':r},note+remains.get(id,'Геометрию и перемещение определяет мастер.'),status)
# Separate stages never share a saving throw accidentally.
patch(6146,{'damage':damage([(10,4,8)],[(2,4,8)],'dex'),'rolls':[stage('Кислота в конце следующего хода',damage([(5,4,8)]),'Только цель, провалившая первоначальный спасбросок; повторного спасброска нет.')]},'Правила 2024: первоначальные 10к4 (+2к4 за круг), спасбросок Ловкости и половина при успехе; отдельные 5к4 в конце следующего хода только при провале. Момент повторного урона отмечается вручную.','full')
patch(6198,{'damage':damage([(1,10,1)],attack=True),'rolls':[stage('Взрыв льда',damage([(2,6,13)],[(1,6,13)],'dex','negate'),'После попадания или промаха: цель и существа в 5 футах.')]},'Правила 2024: отдельное попадание 1к10 и взрыв 2к6 со спасброском Ловкости независимо от попадания. Усиливается только взрыв; формулы и применение этапов поддержаны.','full')
patch(6186,{'damage':damage([(4,4,8)],[(1,4,8)],attack=True),'rolls':[stage('Кислота в конце следующего хода',damage([(2,4,8)],[(1,4,8)]),'Только после попадания; повторного спасброска нет.')]},'Правила 2024: атака и отдельные формулы начального/последующего урона с усилением. При промахе половина только начального урона; мастер выбирает её в окне применения. Напоминание о позднем уроне пока вручную.')
patch(6231,{'rolls':[stage('Урон основной цели',damage([(4,8,9)],[(1,8,9)]),'Заменяет весь урон и эффекты исходной атаки; при промахе половина.'),stage('Разряд вокруг цели',damage([(2,8,9)],[(1,8,9)],'dex'),'Существа в 10 футах от основной цели.')]},'Правила 2024: раздельные формулы основной цели и взрыва, усиление обоих и спасбросок только для взрыва. Замена исходной атаки и выбор половины при промахе пока вручную.')
for id,part,add,condition in [(6075,(2,8,7),(1,8,7),'Дополнительный урон после попадания; против исчадия/нежити ещё 1к8.'),(6128,(2,6,6),(1,6,6),'Дополнительный урон после попадания, затем отдельный спасбросок Силы от толчка/падения.'),(6257,(4,6,11),(1,6,11),'Дополнительный урон после попадания, затем отдельный спасбросок Мудрости от ошеломления.')]:
 fields={'rolls':[stage('Дополнительный урон попадания',damage([part],[add]),condition)]}
 if id==6075:fields['rolls'].append(stage('Дополнительно против исчадия или нежити',damage([(1,8,7)])))
 else:fields['damage']={'save_ability':'str' if id==6128 else 'wis','save_manual':True,'save_condition':condition}
 patch(id,fields,'Правила 2024: дополнительный урон отделён от вторичного спасброска. Встраивание в выбранное оружие, удвоение костей при критическом попадании и условные состояния пока требуют отдельной настройки.')
for id,part,add,condition in [(6163,(1,8,7),(1,8,7),'Попадание; до конца следующего хода заклинателя цель не получает преимуществ невидимости.'),(6165,(1,6,11),(1,6,11),'Провал спасброска Мудрости.'),(6196,(1,10,10),(1,10,10),'Попадание; до конца следующего хода заклинателя цель не восстанавливает ХП.'),(6203,(2,8,4),(1,8,4),'Попадание; цель отравлена до конца следующего хода заклинателя.'),(6205,(1,8,13),(1,8,13),'Попадание; скорость -10 до начала следующего хода заклинателя.'),(6453,(1,8,9),(1,8,9),'Попадание; только провоцированные атаки запрещены до начала следующего хода заклинателя.')]:
 r=damage([part],[add],save='wis' if id==6165 else '',on='negate',attack=id!=6165,scaling='slot' if id==6203 else 'cantrip')
 patch(id,{'damage':r},'Правила 2024: атака или спасбросок, усиление, тип урона и применение результата. '+condition+(' Дополнительное ограничение пока соблюдается участниками.' if id in [6163,6196,6453] else ' Связанный эффект применяется из хроники.'),'full' if id in [6165,6205] else 'partial')
# Explicitly reviewed source effects; descriptions/conditions differ between editions.
effect(6165,4819,'Провал спасброска Мудрости.')
effect(6205,4823,'После попадания лучом.')
effect(6203,4599,'После попадания; до конца следующего хода заклинателя.',{'kind':'custom','text':'До конца следующего хода заклинателя'},[{'kind':'roll_mode','mode':'disadvantage','scopes':['attack','ability_check','skill_check']}])
effect(6378,4832,'Первоначальный спасбросок Интеллекта провален.')
effect(6397,4705,'Первоначальный спасбросок Телосложения провален.')
# Independent beams use the same cast runner, permitting repeated targets where allowed.
for id,old,repeat in [(6225,500,True),(6282,782,True),(6427,1205,False),(500,500,True),(782,782,True),(1205,1205,False)]:
 r=copy.deepcopy(s[old]['data']['damage']);r['attack_chain']={'trigger':'none','unique':'none' if repeat else 'target'}
 patch(id,{'damage':r},'Серия отдельных атак и урона в хронике сессии: '+('лучи можно направлять в одну или разные цели.' if repeat else 'до пяти разных целей, повторная цель запрещена.')+' Число лучей учитывает усиление; ячейка расходуется один раз. Без сессии остаются отдельные броски с показом общего числа лучей.','partial')
patch(6272,{'rolls':[{'kind':'effect','label':'Число дополнительных ходов','dices':[{'count':1,'dice_id':'d4','bonus':1}],'scaling':'none'}]},'Правила 2024: бросок 1к4 + 1 дополнительных ходов. Очерёдность боя и досрочное завершение при воздействии на других пока отмечаются вручную.')
patch(6286,{'rolls':[stage('Неудачная телепортация',damage([(4,6,12)]),'Только если место назначения занято; обе перемещаемые цели получают урон.')]},'Правила 2024: условный урон 4к6 при занятом месте назначения выделен отдельно. Само перемещение разрешается участниками.')
patch(6386,{'rolls':[stage('Цель с более чем 100 ХП',damage([(12,12,11)]),'Только если текущие ХП цели больше 100.')]},'Правила 2024: 12к12 психического урона при ХП выше 100. Мгновенная смерть при 100 ХП и меньше, проверки иммунитетов и предотвращение смерти пока вручную.')
r=damage([(5,6,6)],save='con');r['dices'].append({'count':5,'dice_id':'d6'});r['type_choices']=[7,10]
patch(6356,{'damage':r},'Правила 2024: 5к6 звуком плюс 5к6 излучением или некротической энергией по выбору. Спасбросок Телосложения, половина при успехе; падение при провале пока отмечается вручную.')
r=damage([(1,8,0)],[(1,8,0)],attack=True,scaling='cantrip');r['type_choices']=[6,8,5,11,13,9,4]
for key in ['dices','addon']:
 for row in r[key]:row.pop('type')
patch(6448,{'damage':r},'Правила 2024: атака, выбор типа, крит и усиление заговора. Взрывающиеся к8 с общим лимитом по модификатору заклинателя ещё требуют нового механизма; дополнительные кости пока бросаются вручную.')
r=damage([(1,4,12)]);r['dices'][0]['bonus']=1;r.update(instances=3,addon_instances=1,scaling='slot')
patch(6093,{'damage':r},'Правила 2024: 1к4 + 1 силовым полем за дротик, 3 дротика и +1 за круг выше. Распределение автоматических попаданий и счётчик оставшихся дротиков пока вручную; бросок и применение относятся к одному дротику.')
patch(6347,{'rolls':[{'kind':'effect','label':'Временные хиты','dices':[{'count':2,'dice_id':'d4','bonus':4}],'addon':[{'bonus':5}],'scaling':'slot'}]},'Правила 2024: формула 2к4 + 4 временных ХП, +5 за круг выше. Применение временных ХП заклинанием пока вручную; они не складываются с имеющимися и не являются лечением.')
patch(6230,{'heal':{'dices':[{'count':2,'dice_id':'d8'}],'addon':[{'count':1,'dice_id':'d8'}],'scaling':'slot','apply':False}},'Правила 2024: формула 2к8 без модификатора, +1к8 за круг выше. Короткий отдых до пяти целей и запрет повторного получения до долгого отдыха требуют отдельного сценария; кнопка автоматического лечения намеренно отключена.')
for name,data in [('plan',list(plans.values())),('effects',effects)]: (root/f'{name}.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
print('Prepared',len(plans),'spells and',len(effects),'effects')
